import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import { Calendar, Check, X, Plus } from 'lucide-react';
import axios from 'axios';
import toast from 'react-hot-toast';

const DailyTracker = () => {
    const { user, token } = useAuth();
    const [tasks, setTasks] = useState([]);
    const [selectedDay, setSelectedDay] = useState(null);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        if (user) {
            fetchTasks();
        }
    }, [user]);

    const fetchTasks = async () => {
        try {
            const response = await axios.get(
                `http://localhost:8081/api/tasks/user/${user.id}`,
                { headers: { Authorization: `Bearer ${token}` } }
            );
            setTasks(response.data);
            setLoading(false);
        } catch (error) {
            console.error('Failed to fetch tasks:', error);
            setLoading(false);
        }
    };

    const createTaskForDay = async (day) => {
        try {
            const date = new Date(2026, 6, day); // July 2026 (month 6 = July)
            const dateStr = date.toISOString().split('T')[0];
            
            const response = await axios.post(
                `http://localhost:8081/api/tasks/user/${user.id}/day/${day}?date=${dateStr}`,
                {},
                { headers: { Authorization: `Bearer ${token}` } }
            );
            return response.data;
        } catch (error) {
            console.error('Failed to create task:', error);
            return null;
        }
    };

    const toggleTask = async (taskId, field) => {
        const task = tasks.find(t => t.id === taskId);
        if (!task) return;

        const updatedTask = { 
            ...task, 
            [field]: !task[field] 
        };
        
        try {
            const response = await axios.put(
                `http://localhost:8081/api/tasks/${taskId}`,
                updatedTask,
                { headers: { Authorization: `Bearer ${token}` } }
            );
            setTasks(tasks.map(t => t.id === taskId ? response.data : t));
            toast.success('Task updated successfully');
        } catch (error) {
            toast.error('Failed to update task');
        }
    };

    const handleDayClick = async (day) => {
        setSelectedDay(day);
        
        // Check if tasks exist for this day
        let dayTasks = tasks.filter(task => task.day === day);
        
        if (dayTasks.length === 0) {
            // Create tasks for this day
            const newTask = await createTaskForDay(day);
            if (newTask) {
                setTasks([...tasks, newTask]);
                toast.success(`Tasks created for Day ${day}`);
            }
        }
    };

    const getDayTasks = (day) => {
        return tasks.filter(task => task.day === day);
    };

    if (loading) {
        return (
            <div className="flex items-center justify-center h-64">
                <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600"></div>
            </div>
        );
    }

    const taskLabels = [
        { key: 'javaCompleted', label: 'Java (1.5h)' },
        { key: 'leetcodeCompleted', label: 'LeetCode (1+)' },
        { key: 'dsaCompleted', label: 'DSA/OOP (1h)' },
        { key: 'sqlCompleted', label: 'SQL/APIs/Open Source (1h)' },
        { key: 'projectCompleted', label: 'Project Dev (2-3h)' },
        { key: 'githubCompleted', label: 'GitHub/Portfolio (30m)' }
    ];

    // Generate calendar for July 2026
    const generateCalendar = () => {
        const days = [];
        const firstDayOfMonth = new Date(2026, 6, 1).getDay(); // 0 = Sunday
        
        // Add empty cells for days before month starts
        for (let i = 0; i < firstDayOfMonth; i++) {
            days.push(null);
        }
        
        // Add days 1-31
        for (let day = 1; day <= 31; day++) {
            days.push(day);
        }
        
        return days;
    };

    const calendarDays = generateCalendar();
    const weekDays = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];

    return (
        <div className="bg-white rounded-lg shadow-lg p-6">
            <h1 className="text-2xl font-bold mb-6 flex items-center gap-2">
                <Calendar className="text-blue-600" />
                Daily Task Tracker - July 2026
            </h1>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                <div className="bg-gray-50 rounded-lg p-4">
                    <h2 className="text-lg font-semibold mb-4">Calendar View</h2>
                    <div className="grid grid-cols-7 gap-2">
                        {weekDays.map(day => (
                            <div key={day} className="text-center text-sm font-medium text-gray-600">
                                {day}
                            </div>
                        ))}
                        {calendarDays.map((day, index) => {
                            if (day === null) {
                                return <div key={`empty-${index}`} className="aspect-square"></div>;
                            }
                            
                            const dayTasks = getDayTasks(day);
                            const isCompleted = dayTasks.some(t => t.overallCompleted);
                            const hasTasks = dayTasks.length > 0;
                            
                            return (
                                <div
                                    key={day}
                                    className={`aspect-square rounded-lg flex items-center justify-center cursor-pointer transition-all text-sm font-medium
                                        ${isCompleted ? 'bg-green-500 text-white hover:bg-green-600' : ''}
                                        ${!isCompleted && hasTasks ? 'bg-yellow-200 text-gray-700 hover:bg-yellow-300' : ''}
                                        ${!isCompleted && !hasTasks ? 'bg-white border-2 border-gray-200 hover:border-blue-400 text-gray-700' : ''}
                                        ${selectedDay === day ? 'ring-2 ring-blue-500' : ''}
                                    `}
                                    onClick={() => handleDayClick(day)}
                                >
                                    {day}
                                </div>
                            );
                        })}
                    </div>
                    <div className="mt-4 flex gap-4 text-sm">
                        <div className="flex items-center gap-2">
                            <div className="w-4 h-4 bg-green-500 rounded"></div>
                            <span>Completed</span>
                        </div>
                        <div className="flex items-center gap-2">
                            <div className="w-4 h-4 bg-yellow-200 rounded border border-gray-300"></div>
                            <span>In Progress</span>
                        </div>
                        <div className="flex items-center gap-2">
                            <div className="w-4 h-4 bg-white rounded border-2 border-gray-300"></div>
                            <span>Not Started</span>
                        </div>
                    </div>
                </div>

                <div className="bg-gray-50 rounded-lg p-4">
                    <h2 className="text-lg font-semibold mb-4">
                        {selectedDay ? `Day ${selectedDay} Tasks - July 2026` : 'Click a day to start tracking'}
                    </h2>
                    
                    {selectedDay && (
                        <div className="space-y-3">
                            {taskLabels.map(({ key, label }) => {
                                const dayTasks = getDayTasks(selectedDay);
                                const task = dayTasks.length > 0 ? dayTasks[0] : null;
                                const isCompleted = task ? task[key] : false;
                                const taskExists = task !== null;
                                
                                if (!taskExists) {
                                    return (
                                        <div
                                            key={key}
                                            className="flex items-center justify-between bg-white p-3 rounded-lg shadow-sm opacity-50"
                                        >
                                            <span className="text-gray-500">{label}</span>
                                            <span className="text-gray-400 text-sm">Click to create</span>
                                        </div>
                                    );
                                }
                                
                                return (
                                    <div
                                        key={key}
                                        className={`flex items-center justify-between bg-white p-3 rounded-lg shadow-sm transition-all
                                            ${isCompleted ? 'border-l-4 border-green-500' : 'border-l-4 border-gray-300'}`}
                                    >
                                        <span className={`${isCompleted ? 'text-gray-500 line-through' : 'text-gray-700'}`}>
                                            {label}
                                        </span>
                                        <button
                                            onClick={() => toggleTask(task.id, key)}
                                            className={`p-2 rounded-lg transition-all ${
                                                isCompleted 
                                                    ? 'bg-green-500 text-white hover:bg-green-600' 
                                                    : 'bg-gray-200 text-gray-600 hover:bg-gray-300'
                                            }`}
                                        >
                                            {isCompleted ? <Check size={20} /> : <X size={20} />}
                                        </button>
                                    </div>
                                );
                            })}

                            {getDayTasks(selectedDay).length === 0 && (
                                <div className="text-center py-8">
                                    <p className="text-gray-500 mb-4">No tasks for this day yet</p>
                                    <button
                                        onClick={() => handleDayClick(selectedDay)}
                                        className="bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700 transition flex items-center gap-2 mx-auto"
                                    >
                                        <Plus size={20} />
                                        Create Tasks for Day {selectedDay}
                                    </button>
                                </div>
                            )}
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

export default DailyTracker;
